\"csi\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.CSIPersistentVolumeSource\"},\"fc\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.FCVolumeSource\"},\"flexVolume\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.FlexPersistentVolumeSource\"},\"flocker\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.FlockerVolumeSource\"},\"gcePersistentDisk\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.GCEPersistentDiskVolumeSource\"},\"glusterfs\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.GlusterfsPersistentVolumeSource\"},\"hostPath\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.HostPathVolumeSource\"},\"iscsi\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.ISCSIPersistentVolumeSource\"},\"local\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.LocalVolumeSource\"},\"mountOptions\":{\"description\":\"mountOptions is the list of mount options, e.g. [\\\"ro\\\", \\\"soft\\\"]. Not validated - mount will simply fail if one is invalid. More info: https://kubernetes.io/docs/concepts/storage/persistent-volumes/#mount-options\",\"items\":{\"default\":\"\",\"type\":\"string\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"atomic\",\"nullable\":true},\"nfs\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.NFSVolumeSource\"},\"nodeAffinity\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.VolumeNodeAffinity\"},\"persistentVolumeReclaimPolicy\":{\"description\":\"persistentVolumeReclaimPolicy defines what happens to a persistent volume when released from its claim. Valid options are Retain (default for manually created PersistentVolumes), Delete (default for dynamically provisioned PersistentVolumes), and Recycle (deprecated). Recycle must be supported by the volume plugin underlying this PersistentVolume. More info: https://kubernetes.io/docs/concepts/storage/persistent-volumes#reclaiming\",\"type\":\"string\"},\"photonPersistentDisk\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.PhotonPersistentDiskVolumeSource\"},\"portworxVolume\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.PortworxVolumeSource\"},\"quobyte\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.QuobyteVolumeSource\"},\"rbd\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.RBDPersistentVolumeSource\"},\"scaleIO\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.ScaleIOPersistentVolumeSource\"},\"storageClassName\":{\"description\":\"storageClassName is the name of StorageClass to which this persistent volume belongs. Empty value means that this volume does not belong to any StorageClass.\",\"type\":\"string\"},\"storageos\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.StorageOSPersistentVolumeSource\"},\"volumeAttributesClassName\":{\"description\":\"Name of VolumeAttributesClass to which this persistent volume belongs. Empty value is not allowed. When this field is not set, it indicates that this volume does not belong to any VolumeAttributesClass. This field is mutable and can be changed by the CSI driver after a volume has been updated successfully to a new class. For an unbound PersistentVolume, the volumeAttributesClassName will be matched with unbound PersistentVolumeClaims during the binding process.\",\"type\":\"string\"},\"volumeMode\":{\"description\":\"volumeMode defines if a volume is intended to be used with a formatted filesystem or to remain in raw block state. Value of Filesystem is implied when not included in spec.\",\"type\":\"string\"},\"vsphereVolume\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.VsphereVirtualDiskVolumeSource\"}},\"type\":\"object\"},\"io.k8s.api.core.v1.PhotonPersistentDiskVolumeSource\":{\"description\":\"Represents a Photon Controller persistent disk resource.\",\"properties\":{\"fsType\":{\"description\":\"fsType is the filesystem type to mount. Must be a filesystem type supported by the host operating system. Ex. \\\"ext4\\\", \\\"xfs\\\", \\\"ntfs\\\". Implicitly inferred to be \\\"ext4\\\" if unspecified.\",\"type\":\"string\"},\"pdID\":{\"default\":\"\",\"description\":\"pdID is the ID that identifies Photon Controller persistent disk\",\"type\":\"string\"}},\"required\":[\"pdID\"],\"type\":\"object\"},\"io.k8s.api.core.v1.PortworxVolumeSource\":{\"description\":\"PortworxVolumeSource represents a Portworx volume resource.\",\"properties\":{\"fsType\":{\"description\":\"fSType represents the filesystem type to mount Must be a filesystem type supported by the host operating system. Ex. \\\"ext4\\\", \\\"xfs\\\". Implicitly inferred to be \\\"ext4\\\" if unspecified.\",\"type\":\"string\"},\"readOnly\":{\"description\":\"readOnly defaults to false (read/write). ReadOnly here will force the ReadOnly setting in VolumeMounts.\",\"type\":\"boolean\"},\"volumeID\":{\"default\":\"\",\"description\":\"volumeID uniquely identifies a Portworx volume\",\"type\":\"string\"}},\"required\":[\"volumeID\"],\"type\":\"object\"},\"io.k8s.api.core.v1.QuobyteVolumeSource\":{\"description\":\"Represents a Quobyte mount that lasts the lifetime of a pod. Quobyte volumes do not support ownership management or SELinux relabeling.\",\"properties\":{\"group\":{\"description\":\"group to map volume access to Default is no group\",\"type\":\"string\"},\"readOnly\":{\"description\":\"readOnly here will force the Quobyte volume to be mounted with read-only permissions. Defaults to false.\",\"type\":\"boolean\"},\"registry\":{\"default\":\"\",\"description\":\"registry represents a single or multiple Quobyte Registry services specified as a string as host:port pair (multiple entries are separated with commas) which acts as the central registry for volumes\",\"type\":\"string\"},\"tenant\":{\"description\":\"tenant owning the given Quobyte volume in the Backend Used with dynamically provisioned Quobyte volumes, value is set by the plugin\",\"type\":\"string\"},\"user\":{\"description\":\"user to map volume access to Defaults to serivceaccount user\",\"type\":\"string\"},\"volume\":{\"default\":\"\",\"description\":\"volume is a string that references an already created Quobyte volume by name.\",\"type\":\"string\"}},\"required\":[\"registry\",\"volume\"],\"type\":\"object\"},\"io.k8s.api.core.v1.RBDPersistentVolumeSource\":{\"description\":\"Represents a Rados Block Device mount that lasts the lifetime of a pod. RBD volumes support ownership management and SELinux relabeling.\",\"properties\":{\"fsType\":{\"description\":\"fsType is the filesystem type of the volume that you want to mount. Tip: Ensure that the filesystem type is supported by the host operating system. Examples: \\\"ext4\\\", \\\"xfs\\\", \\\"ntfs\\\". Implicitly inferred to be \\\"ext4\\\" if unspecified. More info: https://kubernetes.io/docs/concepts/storage/volumes#rbd\",\"type\":\"string\"},\"image\":{\"default\":\"\",\"description\":\"image is the rados image name. More info: https://examples.k8s.io/volumes/rbd/README.md#how-to-use-it\",\"type\":\"string\"},\"keyring\":{\"default\":\"/etc/ceph/keyring\",\"description\":\"keyring is the path to key ring for RBDUser. Default is /etc/ceph/keyring. More info: https://examples.k8s.io/volumes/rbd/README.md#how-to-use-it\",\"type\":\"string\"},\"monitors\":{\"description\":\"monitors is a collection of Ceph monitors. More info: https://examples.k8s.io/volumes/rbd/README.md#how-to-use-it\",\"items\":{\"default\":\"\",\"type\":\"string\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"atomic\",\"nullable\":true},\"pool\":{\"default\":\"rbd\",\"description\":\"pool is the rados pool name. Default is rbd. More info: https://examples.k8s.io/volumes/rbd/README.md#how-to-use-it\",\"type\":\"string\"},\"readOnly\":{\"description\":\"readOnly here will force the ReadOnly setting in VolumeMounts. Defaults to false. More info: https://examples.k8s.io/volumes/rbd/README.md#how-to-use-it\",\"type\":\"boolean\"},\"secretRef\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.SecretReference\"},\"user\":{\"default\":\"admin\",\"description\":\"user is the rados user name. Default is admin. More info: https://examples.k8s.io/volumes/rbd/README.md#how-to-use-it\",\"type\":\"string\"}},\"required\":[\"monitors\",\"image\"],\"type\":\"object\"},\"io.k8s.api.core.v1.ScaleIOPersistentVolumeSource\":{\"description\":\"ScaleIOPersistentVolumeSource represents a persistent ScaleIO volume\",\"properties\":{\"fsType\":{\"default\":\"xfs\",\"description\":\"fsType is the filesystem type to mount. Must be a filesystem type supported by the host operating system. Ex. \\\"ext4\\\", \\\"xfs\\\", \\\"ntfs\\\". Default is \\\"xfs\\\"\",\"type\":\"string\"},\"gateway\":{\"default\":\"\",\"description\":\"gateway is the host address of the ScaleIO API Gateway.\",\"type\":\"string\"},\"protectionDomain\":{\"description\":\"protectionDomain is the name of the ScaleIO Protection Domain for the configured storage.\",\"type\":\"string\"},\"readOnly\":{\"description\":\"readOnly defaults to false (read/write). ReadOnly here will force the ReadOnly setting in VolumeMounts.\",\"type\":\"boolean\"},\"secretRef\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.SecretReference\"},\"sslEnabled\":{\"description\":\"sslEnabled is the flag to enable/disable SSL communication with Gateway, default false\",\"type\":\"boolean\"},\"storageMode\":{\"default\":\"ThinProvisioned\",\"description\":\"storageMode indicates whether the storage for a volume should be ThickProvisioned or ThinProvisioned. Default is ThinProvisioned.\",\"type\":\"string\"},\"storagePool\":{\"description\":\"storagePool is the ScaleIO Storage Pool associated with the protection domain.\",\"type\":\"string\"},\"system\":{\"default\":\"\",\"description\":\"system is the name of the storage system as configured in ScaleIO.\",\"type\":\"string\"},\"volumeName\":{\"description\":\"volumeName is the name of a volume already created in the ScaleIO system that is associated with this volume source.\",\"type\":\"string\"}},\"required\":[\"gateway\",\"system\",\"secretRef\"],\"type\":\"object\"},\"io.k8s.api.core.v1.SecretReference\":{\"description\":\"SecretReference represents a Secret Reference. It has enough information to retrieve secret in any namespace\",\"properties\":{\"name\":{\"description\":\"name is unique within a namespace to reference a secret resource.\",\"type\":\"string\"},\"namespace\":{\"description\":\"namespace defines the space within which the secret name must be unique.\",\"type\":\"string\"}},\"type\":\"object\",\"x-kubernetes-map-type\":\"atomic\"},\"io.k8s.api.core.v1.StorageOSPersistentVolumeSource\":{\"description\":\"Represents a StorageOS persistent volume resource.\",\"properties\":{\"fsType\":{\"description\":\"fsType is the filesystem type to mount. Must be a filesystem type supported by the host operating system. Ex. \\\"ext4\\\", \\\"xfs\\\", \\\"ntfs\\\". Implicitly inferred to be \\\"ext4\\\" if unspecified.\",\"type\":\"string\"},\"readOnly\":{\"description\":\"readOnly defaults to false (read/write). ReadOnly here will force the ReadOnly setting in VolumeMounts.\",\"type\":\"boolean\"},\"secretRef\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.ObjectReference\"},\"volumeName\":{\"description\":\"volumeName is the human-readable name of the StorageOS volume.  Volume names are only unique within a namespace.\",\"type\":\"string\"},\"volumeNamespace\":{\"description\":\"volumeNamespace specifies the scope of the volume within StorageOS.  If no namespace is specified then the Pod's namespace will be used.  This allows the Kubernetes name scoping to be mirrored within StorageOS for tighter integration. Set VolumeName to any name to override the default behaviour. Set to \\\"default\\\" if you are not using namespaces within StorageOS. Namespaces that do not pre-exist within StorageOS will be created.\",\"type\":\"string\"}},\"type\":\"object\"},\"io.k8s.api.core.v1.TopologySelectorLabelRequirement\":{\"description\":\"A topology selector requirement is a selector that matches given label. This is an alpha feature and may change in the future.\",\"properties\":{\"key\":{\"default\":\"\",\"description\":\"The label key that the selector applies to.\",\"type\":\"string\"},\"values\":{\"description\":\"An array of string values. One value must match the label to be selected. Each entry in Values is ORed.\",\"items\":{\"default\":\"\",\"type\":\"string\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"atomic\",\"nullable\":true}},\"required\":[\"key\",\"values\"],\"type\":\"object\"},\"io.k8s.api.core.v1.TopologySelectorTerm\":{\"description\":\"A topology selector term represents the result of label queries. A null or empty topology selector term matches no objects. The requirements of them are ANDed. It provides a subset of functionality as NodeSelectorTerm. This is an alpha feature and may change in the future.\",\"properties\":{\"matchLabelExpressions\":{\"description\":\"A list of topology selector requirements by labels.\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.TopologySelectorLabelRequirement\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"atomic\",\"nullable\":true}},\"type\":\"object\",\"x-kubernetes-map-type\":\"atomic\"},\"io.k8s.api.core.v1.VolumeNodeAffinity\":{\"description\":\"VolumeNodeAffinity defines constraints that limit what nodes this volume can be accessed from.\",\"properties\":{\"required\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.NodeSelector\"}},\"type\":\"object\"},\"io.k8s.api.core.v1.VsphereVirtualDiskVolumeSource\":{\"description\":\"Represents a vSphere volume resource.\",\"properties\":{\"fsType\":{\"description\":\"fsType is filesystem type to mount. Must be a filesystem type supported by the host operating system. Ex. \\\"ext4\\\", \\\"xfs\\\", \\\"ntfs\\\". Implicitly inferred to be \\\"ext4\\\" if unspecified.\",\"type\":\"string\"},\"storagePolicyID\":{\"description\":\"storagePolicyID is the storage Policy Based Management (SPBM) profile ID associated with the StoragePolicyName.\",\"type\":\"string\"},\"storagePolicyName\":{\"description\":\"storagePolicyName is the storage Policy Based Management (SPBM) profile name.\",\"type\":\"string\"},\"volumePath\":{\"default\":\"\",\"description\":\"volumePath is the path that identifies vSphere volume vmdk\",\"type\":\"string\"}},\"required\":[\"volumePath\"],\"type\":\"object\"},\"io.k8s.api.storage.v1.CSIDriver\":{\"description\":\"CSIDriver captures information about a Container Storage Interface (CSI) volume driver deployed on the cluster. Kubernetes attach detach controller uses this object to determine whether attach is required. Kubelet uses this object to determine whether pod information needs to be passed on mount. CSIDriver objects are non-namespaced.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"metadata\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.ObjectMeta\"},\"spec\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.CSIDriverSpec\"}},\"required\":[\"spec\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"storage.k8s.io\",\"kind\":\"CSIDriver\",\"version\":\"v1\"}]},\"io.k8s.api.storage.v1.CSIDriverList\":{\"description\":\"CSIDriverList is a collection of CSIDriver objects.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"items\":{\"description\":\"items is the list of CSIDriver\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.CSIDriver\"},\"type\":[\"array\",\"null\"],\"nullable\":true},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"metadata\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.ListMeta\"}},\"required\":[\"items\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"storage.k8s.io\",\"kind\":\"CSIDriverList\",\"version\":\"v1\"}]},\"io.k8s.api.storage.v1.CSIDriverSpec\":{\"description\":\"CSIDriverSpec is the specification of a CSIDriver.\",\"properties\":{\"attachRequired\":{\"description\":\"attachRequired indicates this CSI volume driver requires an attach operation (because it implements the CSI ControllerPublishVolume() method), and that the Kubernetes attach detach controller should call the attach volume interface which checks the volumeattachment status and waits until the volume is attached before proceeding to mounting. The CSI external-attacher coordinates with CSI volume driver and updates the volumeattachment status when the attach operation is complete. If the value is specified to false, the attach operation will be skipped. Otherwise the attach operation will be called.\\n\\nThis field is immutable.\",\"type\":\"boolean\"},\"fsGroupPolicy\":{\"description\":\"fsGroupPolicy defines if the underlying volume supports changing ownership and permission of the volume before being mounted. Refer to the specific FSGroupPolicy values for additional details.\\n\\nThis field was immutable in Kubernetes < 1.29 and now is mutable.\\n\\nDefaults to ReadWriteOnceWithFSType, which will examine each volume to determine if Kubernetes should modify ownership and permissions of the volume. With the default policy the defined fsGroup will only be applied if a fstype is defined and the volume's access mode contains ReadWriteOnce.\",\"type\":\"string\"},\"nodeAllocatableUpdatePeriodSeconds\":{\"description\":\"nodeAllocatableUpdatePeriodSeconds specifies the interval between periodic updates of the CSINode allocatable capacity for this driver. When set, both periodic updates and updates triggered by capacity-related failures are enabled. If not set, no updates occur (neither periodic nor upon detecting capacity-related failures), and the allocatable.count remains static. The minimum allowed value for this field is 10 seconds.\\n\\nThis is a beta feature and requires the MutableCSINodeAllocatableCount feature gate to be enabled.\\n\\nThis field is mutable.\",\"format\":\"int64\",\"type\":\"integer\"},\"podInfoOnMount\":{\"description\":\"podInfoOnMount indicates this CSI volume driver requires additional pod information (like podName, podUID, etc.) during mount operations, if set to true. If set to false, pod information will not be passed on mount. Default is false.\\n\\nThe CSI driver specifies podInfoOnMount as part of driver deployment. If true, Kubelet will pass pod information as VolumeContext in the CSI NodePublishVolume() calls. The CSI driver is responsible for parsing and validating the information passed in as VolumeContext.\\n\\nThe following VolumeContext will be passed if podInfoOnMount is set to true. This list might grow, but the prefix will be used. \\\"csi.storage.k8s.io/pod.name\\\": pod.Name \\\"csi.storage.k8s.io/pod.namespace\\\": pod.Namespace \\\"csi.storage.k8s.io/pod.uid\\\": string(pod.UID) \\\"csi.storage.k8s.io/ephemeral\\\": \\\"true\\\" if the volume is an ephemeral inline volume\\n                                defined by a CSIVolumeSource, otherwise \\\"false\\\"\\n\\n\\\"csi.storage.k8s.io/ephemeral\\\" is a new feature in Kubernetes 1.16. It is only required for drivers which support both the \\\"Persistent\\\" and \\\"Ephemeral\\\" VolumeLifecycleMode. Other drivers can leave pod info disabled and/or ignore this field. As Kubernetes 1.15 doesn't support this field, drivers can only support one mode when deployed on such a cluster and the deployment determines which mode that is, for example via a command line parameter of the driver.\\n\\nThis field was immutable in Kubernetes < 1.29 and now is mutable.\",\"type\":\"boolean\"},\"requiresRepublish\":{\"description\":\"requiresRepublish indicates the CSI driver wants `NodePublishVolume` being periodically called to reflect any possible change in the mounted volume. This field defaults to false.\\n\\nNote: After a successful initial NodePublishVolume call, subsequent calls to NodePublishVolume should only update the contents of the volume. New mount points will not be seen by a running container.\",\"type\":\"boolean\"},\"seLinuxMount\":{\"description\":\"seLinuxMount specifies if the CSI driver supports \\\"-o context\\\" mount option.\\n\\nWhen \\\"true\\\", the CSI driver must ensure that all volumes provided by this CSI driver can be mounted separately with different `-o context` options. This is typical for storage backends that provide volumes as filesystems on block devices or as independent shared volumes. Kubernetes will call NodeStage / NodePublish with \\\"-o context=xyz\\\" mount option when mounting a ReadWriteOncePod volume used in Pod that has explicitly set SELinux context. In the future, it may be expanded to other volume AccessModes. In any case, Kubernetes will ensure that the volume is mounted only with a single SELinux context.\\n\\nWhen \\\"false\\\", Kubernetes won't pass any special SELinux mount options to the driver. This is typical for volumes that represent subdirectories of a bigger shared filesystem.\\n\\nDefault is \\\"false\\\".\",\"type\":\"boolean\"},\"serviceAccountTokenInSecrets\":{\"description\":\"serviceAccountTokenInSecrets is an opt-in for CSI drivers to indicate that service account tokens should be passed via the Secrets field in NodePublishVolumeRequest instead of the VolumeContext field. The CSI specification provides a dedicated Secrets field for sensitive information like tokens, which is the appropriate mechanism for handling credentials. This addresses security concerns where sensitive tokens were being logged as part of volume context.\\n\\nWhen \\\"true\\\", kubelet will pass the tokens only in the Secrets field with the key \\\"csi.storage.k8s.io/serviceAccount.tokens\\\". The CSI driver must be updated to read tokens from the Secrets field instead of VolumeContext.\\n\\nWhen \\\"false\\\" or not set, kubelet will pass the tokens in VolumeContext with the key \\\"csi.storage.k8s.io/serviceAccount.tokens\\\" (existing behavior). This maintains backward compatibility with existing CSI drivers.\\n\\nThis field can only be set when TokenRequests is configured. The API server will reject CSIDriver specs that set this field without TokenRequests.\\n\\nDefault behavior if unset is to pass tokens in the VolumeContext field.\",\"type\":\"boolean\"},\"storageCapacity\":{\"description\":\"storageCapacity indicates that the CSI volume driver wants pod scheduling to consider the storage capacity that the driver deployment will report by creating CSIStorageCapacity objects with capacity information, if set to true.\\n\\nThe check can be enabled immediately when deploying a driver. In that case, provisioning new volumes with late binding will pause until the driver deployment has published some suitable CSIStorageCapacity object.\\n\\nAlternatively, the driver can be deployed with the field unset or false and it can be flipped later when storage capacity information has been published.\\n\\nThis field was immutable in Kubernetes <= 1.22 and now is mutable.\",\"type\":\"boolean\"},\"tokenRequests\":{\"description\":\"tokenRequests indicates the CSI driver needs pods' service account tokens it is mounting volume for to do necessary authentication. Kubelet will pass the tokens in VolumeContext in the CSI NodePublishVolume calls. The CSI driver should parse and validate the following VolumeContext: \\\"csi.storage.k8s.io/serviceAccount.tokens\\\": {\\n  \\\"<audience>\\\": {\\n    \\\"token\\\": <token>,\\n    \\\"expirationTimestamp\\\": <expiration timestamp in RFC3339>,\\n  },\\n  ...\\n}\\n\\nNote: Audience in each TokenRequest should be different and at most one token is empty string. To receive a new token after expiry, RequiresRepublish can be used to trigger NodePublishVolume periodically.\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.TokenRequest\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"atomic\",\"nullable\":true},\"volumeLifecycleModes\":{\"description\":\"volumeLifecycleModes defines what kind of volumes this CSI volume driver supports. The default if the list is empty is \\\"Persistent\\\", which is the usage defined by the CSI specification and implemented in Kubernetes via the usual PV/PVC mechanism.\\n\\nThe other mode is \\\"Ephemeral\\\". In this mode, volumes are defined inline inside the pod spec with CSIVolumeSource and their lifecycle is tied to the lifecycle of that pod. A driver has to be aware of this because it is only going to get a NodePublishVolume call for such a volume.\\n\\nFor more information about implementing this mode, see https://kubernetes-csi.github.io/docs/ephemeral-local-volumes.html A driver can support one or more of these modes and more modes may be added in the future.\\n\\nThis field is beta. This field is immutable.\",\"items\":{\"default\":\"\",\"type\":\"string\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"set\",\"nullable\":true}},\"type\":\"object\"},\"io.k8s.api.storage.v1.CSINode\":{\"description\":\"CSINode holds information about all CSI drivers installed on a node. CSI drivers do not need to create the CSINode object directly. As long as they use the node-driver-registrar sidecar container, the kubelet will automatically populate the CSINode object for the CSI driver as part of kubelet plugin registration. CSINode has the same name as a node. If the object is missing, it means either there are no CSI Drivers available on the node, or the Kubelet version is low enough that it doesn't create this object. CSINode has an OwnerReference that points to the corresponding node object.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"metadata\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.ObjectMeta\"},\"spec\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.CSINodeSpec\"}},\"required\":[\"spec\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"storage.k8s.io\",\"kind\":\"CSINode\",\"version\":\"v1\"}]},\"io.k8s.api.storage.v1.CSINodeDriver\":{\"description\":\"CSINodeDriver holds information about the specification of one CSI driver installed on a node\",\"properties\":{\"allocatable\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.VolumeNodeResources\"},\"name\":{\"default\":\"\",\"description\":\"name represents the name of the CSI driver that this object refers to. This MUST be the same name returned by the CSI GetPluginName() call for that driver.\",\"type\":\"string\"},\"nodeID\":{\"default\":\"\",\"description\":\"nodeID of the node from the driver point of view. This field enables Kubernetes to communicate with storage systems that do not share the same nomenclature for nodes. For example, Kubernetes may refer to a given node as \\\"node1\\\", but the storage system may refer to the same node as \\\"nodeA\\\". When Kubernetes issues a command to the storage system to attach a volume to a specific node, it can use this field to refer to the node name using the ID that the storage system will understand, e.g. \\\"nodeA\\\" instead of \\\"node1\\\". This field is required.\",\"type\":\"string\"},\"topologyKeys\":{\"description\":\"topologyKeys is the list of keys supported by the driver. When a driver is initialized on a cluster, it provides a set of topology keys that it understands (e.g. \\\"company.com/zone\\\", \\\"company.com/region\\\"). When a driver is initialized on a node, it provides the same topology keys along with values. Kubelet will expose these topology keys as labels on its own node object. When Kubernetes does topology aware provisioning, it can use this list to determine which labels it should retrieve from the node object and pass back to the driver. It is possible for different nodes to use different topology keys. This can be empty if driver does not support topology.\",\"items\":{\"default\":\"\",\"type\":\"string\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"atomic\",\"nullable\":true}},\"required\":[\"name\",\"nodeID\"],\"type\":\"object\"},\"io.k8s.api.storage.v1.CSINodeList\":{\"description\":\"CSINodeList is a collection of CSINode objects.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"items\":{\"description\":\"items is the list of CSINode\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.CSINode\"},\"type\":[\"array\",\"null\"],\"nullable\":true},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"metadata\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.ListMeta\"}},\"required\":[\"items\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"storage.k8s.io\",\"kind\":\"CSINodeList\",\"version\":\"v1\"}]},\"io.k8s.api.storage.v1.CSINodeSpec\":{\"description\":\"CSINodeSpec holds information about the specification of all CSI drivers installed on a node\",\"properties\":{\"drivers\":{\"description\":\"drivers is a list of information of all CSI Drivers existing on a node. If all drivers in the list are uninstalled, this can become empty.\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.CSINodeDriver\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-map-keys\":[\"name\"],\"x-kubernetes-list-type\":\"map\",\"x-kubernetes-patch-merge-key\":\"name\",\"x-kubernetes-patch-strategy\":\"merge\",\"nullable\":true}},\"required\":[\"drivers\"],\"type\":\"object\"},\"io.k8s.api.storage.v1.CSIStorageCapacity\":{\"description\":\"CSIStorageCapacity stores the result of one CSI GetCapacity call. For a given StorageClass, this describes the available capacity in a particular topology segment.  This can be used when considering where to instantiate new PersistentVolumes.\\n\\nFor example this can express things like: - StorageClass \\\"standard\\\" has \\\"1234 GiB\\\" available in \\\"topology.kubernetes.io/zone=us-east1\\\" - StorageClass \\\"localssd\\\" has \\\"10 GiB\\\" available in \\\"kubernetes.io/hostname=knode-abc123\\\"\\n\\nThe following three cases all imply that no capacity is available for a certain combination: - no object exists with suitable topology and storage class name - such an object exists, but the capacity is unset - such an object exists, but the capacity is zero\\n\\nThe producer of these objects can decide which approach is more suitable.\\n\\nThey are consumed by the kube-scheduler when a CSI driver opts into capacity-aware scheduling with CSIDriverSpec.StorageCapacity. The scheduler compares the MaximumVolumeSize against the requested size of pending volumes to filter out unsuitable nodes. If MaximumVolumeSize is unset, it falls back to a comparison against the less precise Capacity. If that is also unset, the scheduler assumes that capacity is insufficient and tries some other node.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"capacity\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.api.resource.Quantity\"},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"maximumVolumeSize\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.api.resource.Quantity\"},\"metadata\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.ObjectMeta\"},\"nodeTopology\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.LabelSelector\"},\"storageClassName\":{\"default\":\"\",\"description\":\"storageClassName represents the name of the StorageClass that the reported capacity applies to. It must meet the same requirements as the name of a StorageClass object (non-empty, DNS subdomain). If that object no longer exists, the CSIStorageCapacity object is obsolete and should be removed by its creator. This field is immutable.\",\"type\":\"string\"}},\"required\":[\"storageClassName\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"storage.k8s.io\",\"kind\":\"CSIStorageCapacity\",\"version\":\"v1\"}]},\"io.k8s.api.storage.v1.CSIStorageCapacityList\":{\"description\":\"CSIStorageCapacityList is a collection of CSIStorageCapacity objects.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"items\":{\"description\":\"items is the list of CSIStorageCapacity objects.\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.CSIStorageCapacity\"},\"type\":[\"array\",\"null\"],\"nullable\":true},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"metadata\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.ListMeta\"}},\"required\":[\"items\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"storage.k8s.io\",\"kind\":\"CSIStorageCapacityList\",\"version\":\"v1\"}]},\"io.k8s.api.storage.v1.StorageClass\":{\"description\":\"StorageClass describes the parameters for a class of storage for which PersistentVolumes can be dynamically provisioned.\\n\\nStorageClasses are non-namespaced; the name of the storage class according to etcd is in ObjectMeta.Name.\",\"properties\":{\"allowVolumeExpansion\":{\"description\":\"allowVolumeExpansion shows whether the storage class allow volume expand.\",\"type\":\"boolean\"},\"allowedTopologies\":{\"description\":\"allowedTopologies restrict the node topologies where volumes can be dynamically provisioned. Each volume plugin defines its own supported topology specifications. An empty TopologySelectorTerm list means there is no topology restriction. This field is only honored by servers that enable the VolumeScheduling feature.\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.TopologySelectorTerm\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"atomic\",\"nullable\":true},\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"metadata\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.ObjectMeta\"},\"mountOptions\":{\"description\":\"mountOptions controls the mountOptions for dynamically provisioned PersistentVolumes of this storage class. e.g. [\\\"ro\\\", \\\"soft\\\"]. Not validated - mount of the PVs will simply fail if one is invalid.\",\"items\":{\"default\":\"\",\"type\":\"string\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"atomic\",\"nullable\":true},\"parameters\":{\"additionalProperties\":{\"default\":\"\",\"type\":\"string\"},\"description\":\"parameters holds the parameters for the provisioner that should create volumes of this storage class.\",\"type\":\"object\"},\"provisioner\":{\"default\":\"\",\"description\":\"provisioner indicates the type of the provisioner.\",\"type\":\"string\"},\"reclaimPolicy\":{\"description\":\"reclaimPolicy controls the reclaimPolicy for dynamically provisioned PersistentVolumes of this storage class. Defaults to Delete.\",\"type\":\"string\"},\"volumeBindingMode\":{\"description\":\"volumeBindingMode indicates how PersistentVolumeClaims should be provisioned and bound.  When unset, VolumeBindingImmediate is used. This field is only honored by servers that enable the VolumeScheduling feature.\",\"type\":\"string\"}},\"required\":[\"provisioner\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"storage.k8s.io\",\"kind\":\"StorageClass\",\"version\":\"v1\"}]},\"io.k8s.api.storage.v1.StorageClassList\":{\"description\":\"StorageClassList is a collection of storage classes.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"items\":{\"description\":\"items is the list of StorageClasses\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.StorageClass\"},\"type\":[\"array\",\"null\"],\"nullable\":true},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"metadata\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.ListMeta\"}},\"required\":[\"items\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"storage.k8s.io\",\"kind\":\"StorageClassList\",\"version\":\"v1\"}]},\"io.k8s.api.storage.v1.TokenRequest\":{\"description\":\"TokenRequest contains parameters of a service account token.\",\"properties\":{\"audience\":{\"default\":\"\",\"description\":\"audience is the intended audience of the token in \\\"TokenRequestSpec\\\". It will default to the audiences of kube apiserver.\",\"type\":\"string\"},\"expirationSeconds\":{\"description\":\"expirationSeconds is the duration of validity of the token in \\\"TokenRequestSpec\\\". It has the same default value of \\\"ExpirationSeconds\\\" in \\\"TokenRequestSpec\\\".\",\"format\":\"int64\",\"type\":\"integer\"}},\"required\":[\"audience\"],\"type\":\"object\"},\"io.k8s.api.storage.v1.VolumeAttachment\":{\"description\":\"VolumeAttachment captures the intent to attach or detach the specified volume to/from the specified node.\\n\\nVolumeAttachment objects are non-namespaced.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"metadata\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.ObjectMeta\"},\"spec\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.VolumeAttachmentSpec\"},\"status\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.VolumeAttachmentStatus\"}},\"required\":[\"spec\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"storage.k8s.io\",\"kind\":\"VolumeAttachment\",\"version\":\"v1\"}]},\"io.k8s.api.storage.v1.VolumeAttachmentList\":{\"description\":\"VolumeAttachmentList is a collection of VolumeAttachment objects.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"items\":{\"description\":\"items is the list of VolumeAttachments\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.VolumeAttachment\"},\"type\":[\"array\",\"null\"],\"nullable\":true},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"metadata\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.ListMeta\"}},\"required\":[\"items\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"storage.k8s.io\",\"kind\":\"VolumeAttachmentList\",\"version\":\"v1\"}]},\"io.k8s.api.storage.v1.VolumeAttachmentSource\":{\"description\":\"VolumeAttachmentSource represents a volume that should be attached. Right now only PersistentVolumes can be attached via external attacher, in the future we may allow also inline volumes in pods. Exactly one member can be set.\",\"properties\":{\"inlineVolumeSpec\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.core.v1.PersistentVolumeSpec\"},\"persistentVolumeName\":{\"description\":\"persistentVolumeName represents the name of the persistent volume to attach.\",\"type\":\"string\"}},\"type\":\"object\"},\"io.k8s.api.storage.v1.VolumeAttachmentSpec\":{\"description\":\"VolumeAttachmentSpec is the specification of a VolumeAttachment request.\",\"properties\":{\"attacher\":{\"default\":\"\",\"description\":\"attacher indicates the name of the volume driver that MUST handle this request. This is the name returned by GetPluginName().\",\"type\":\"string\"},\"nodeName\":{\"default\":\"\",\"description\":\"nodeName represents the node that the volume should be attached to.\",\"type\":\"string\"},\"source\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.VolumeAttachmentSource\"}},\"required\":[\"attacher\",\"source\",\"nodeName\"],\"type\":\"object\"},\"io.k8s.api.storage.v1.VolumeAttachmentStatus\":{\"description\":\"VolumeAttachmentStatus is the status of a VolumeAttachment request.\",\"properties\":{\"attachError\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.VolumeError\"},\"attached\":{\"default\":false,\"description\":\"attached indicates the volume is successfully attached. This field must only be set by the entity completing the attach operation, i.e. the external-attacher.\",\"type\":\"boolean\"},\"attachmentMetadata\":{\"additionalProperties\":{\"default\":\"\",\"type\":\"string\"},\"description\":\"attachmentMetadata is populated with any information returned by the attach operation, upon successful attach, that must be passed into subsequent WaitForAttach or Mount calls. This field must only be set by the entity completing the attach operation, i.e. the external-attacher.\",\"type\":\"object\"},\"detachError\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.VolumeError\"}},\"required\":[\"attached\"],\"type\":\"object\"},\"io.k8s.api.storage.v1.VolumeAttributesClass\":{\"description\":\"VolumeAttributesClass represents a specification of mutable volume attributes defined by the CSI driver. The class can be specified during dynamic provisioning of PersistentVolumeClaims, and changed in the PersistentVolumeClaim spec after provisioning.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"driverName\":{\"default\":\"\",\"description\":\"Name of the CSI driver This field is immutable.\",\"type\":\"string\"},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"metadata\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.ObjectMeta\"},\"parameters\":{\"additionalProperties\":{\"default\":\"\",\"type\":\"string\"},\"description\":\"parameters hold volume attributes defined by the CSI driver. These values are opaque to the Kubernetes and are passed directly to the CSI driver. The underlying storage provider supports changing these attributes on an existing volume, however the parameters field itself is immutable. To invoke a volume update, a new VolumeAttributesClass should be created with new parameters, and the PersistentVolumeClaim should be updated to reference the new VolumeAttributesClass.\\n\\nThis field is required and must contain at least one key/value pair. The keys cannot be empty, and the maximum number of parameters is 512, with a cumulative max size of 256K. If the CSI driver rejects invalid parameters, the target PersistentVolumeClaim will be set to an \\\"Infeasible\\\" state in the modifyVolumeStatus field.\",\"type\":\"object\"}},\"required\":[\"driverName\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"storage.k8s.io\",\"kind\":\"VolumeAttributesClass\",\"version\":\"v1\"}]},\"io.k8s.api.storage.v1.VolumeAttributesClassList\":{\"description\":\"VolumeAttributesClassList is a collection of VolumeAttributesClass objects.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"items\":{\"description\":\"items is the list of VolumeAttributesClass objects.\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.api.storage.v1.VolumeAttributesClass\"},\"type\":[\"array\",\"null\"],\"nullable\":true},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"metadata\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.ListMeta\"}},\"required\":[\"items\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"storage.k8s.io\",\"kind\":\"VolumeAttributesClassList\",\"version\":\"v1\"}]},\"io.k8s.api.storage.v1.VolumeError\":{\"description\":\"VolumeError captures an error encountered during a volume operation.\",\"properties\":{\"errorCode\":{\"description\":\"errorCode is a numeric gRPC code representing the error encountered during Attach or Detach operations.\\n\\nThis is an optional, beta field that requires the MutableCSINodeAllocatableCount feature gate being enabled to be set.\",\"format\":\"int32\",\"type\":\"integer\"},\"message\":{\"description\":\"message represents the error encountered during Attach or Detach operation. This string may be logged, so it should not contain sensitive information.\",\"type\":\"string\"},\"time\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.Time\"}},\"type\":\"object\"},\"io.k8s.api.storage.v1.VolumeNodeResources\":{\"description\":\"VolumeNodeResources is a set of resource limits for scheduling of volumes.\",\"properties\":{\"count\":{\"description\":\"count indicates the maximum number of unique volumes managed by the CSI driver that can be used on a node. A volume that is both attached and mounted on a node is considered to be used once, not twice. The same rule applies for a unique volume that is shared among multiple pods on the same node. If this field is not specified, then the supported number of volumes on this node is unbounded.\",\"format\":\"int32\",\"type\":\"integer\"}},\"type\":\"object\"},\"io.k8s.apimachinery.pkg.api.resource.Quantity\":{\"description\":\"Quantity is a fixed-point representation of a number. It provides convenient marshaling/unmarshaling in JSON and YAML, in addition to String() and AsInt64() accessors.\\n\\nThe serialization format is:\\n\\n``` <quantity>        ::= <signedNumber><suffix>\\n\\n\\t(Note that <suffix> may be empty, from the \\\"\\\" case in <decimalSI>.)\\n\\n<digit>           ::= 0 | 1 | ... | 9 <digits>          ::= <digit> | <digit><digits> <number>          ::= <digits> | <digits>.<digits> | <digits>. | .<digits> <sign>            ::= \\\"+\\\" | \\\"-\\\" <signedNumber>    ::= <number> | <sign><number> <suffix>          ::= <binarySI> | <decimalExponent> | <decimalSI> <binarySI>        ::= Ki | Mi | Gi | Ti | Pi | Ei\\n\\n\\t(International System of units; See: http://physics.nist.gov/cuu/Units/binary.html)\\n\\n<decimalSI>       ::= m | \\\"\\\" | k | M | G | T | P | E\\n\\n\\t(Note that 1024 = 1Ki but 1000 = 1k; I didn't choose the capitalization.)\\n\\n<decimalExponent> ::= \\\"e\\\" <signedNumber> | \\\"E\\\" <signedNumber> ```\\n\\nNo matter which of the three exponent forms is used, no quantity may represent a number greater than 2^63-1 in magnitude, nor may it have more than 3 decimal places. Numbers larger or more precise will be capped or rounded up. (E.g.: 0.1m will rounded up to 1m.) This may be extended in the future if we require larger or smaller quantities.\\n\\nWhen a Quantity is parsed from a string, it will remember the type of suffix it had, and will use the same type again when it is serialized.\\n\\nBefore serializing, Quantity will be put in \\\"canonical form\\\". This means that Exponent/suffix will be adjusted up or down (with a corresponding increase or decrease in Mantissa) such that:\\n\\n- No precision is lost - No fractional digits will be emitted - The exponent (or suffix) is as large as possible.\\n\\nThe sign will be omitted unless the number is negative.\\n\\nExamples:\\n\\n- 1.5 will be serialized as \\\"1500m\\\" - 1.5Gi will be serialized as \\\"1536Mi\\\"\\n\\nNote that the quantity will NEVER be internally represented by a floating point number. That is the whole point of this exercise.\\n\\nNon-canonical values will still parse as long as they are well formed, but will be re-emitted in their canonical form. (So always use canonical form, or don't diff.)\\n\\nThis format is intended to make it difficult to use these numbers without writing some sort of special handling code in the hopes that that will cause implementors to also use a fixed point implementation.\",\"oneOf\":[{\"type\":\"string\"},{\"type\":\"number\"}]},\"io.k8s.apimachinery.pkg.apis.meta.v1.APIResource\":{\"description\":\"APIResource specifies the name of a resource and whether it is namespaced.\",\"properties\":{\"categories\":{\"description\":\"categories is a list of the grouped resources this resource belongs to (e.g. 'all')\",\"items\":{\"default\":\"\",\"type\":\"string\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"atomic\",\"nullable\":true},\"group\":{\"description\":\"group is the preferred group of the resource.  Empty implies the group of the containing resource list. For subresources, this may have a different value, for example: Scale\\\".\",\"type\":\"string\"},\"kind\":{\"default\":\"\",\"description\":\"kind is the kind for the resource (e.g. 'Foo' is the kind for a resource 'foo')\",\"type\":\"string\"},\"name\":{\"default\":\"\",\"description\":\"name is the plural name of the resource.\",\"type\":\"string\"},\"namespaced\":{\"default\":false,\"description\":\"namespaced indicates if a resource is namespaced or not.\",\"type\":\"boolean\"},\"shortNames\":{\"description\":\"shortNames is a list of suggested short names of the resource.\",\"items\":{\"default\":\"\",\"type\":\"string\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"atomic\",\"nullable\":true},\"singularName\":{\"default\":\"\",\"description\":\"singularName is the singular name of the resource.  This allows clients to handle plural and singular opaquely. The singularName is more correct for reporting status on a single item and both singular and plural are allowed from the kubectl CLI interface.\",\"type\":\"string\"},\"storageVersionHash\":{\"description\":\"The hash value of the storage version, the version this resource is converted to when written to the data store. Value must be treated as opaque by clients. Only equality comparison on the value is valid. This is an alpha feature and may change or be removed in the future. The field is populated by the apiserver only if the StorageVersionHash feature gate is enabled. This field will remain optional even if it graduates.\",\"type\":\"string\"},\"verbs\":{\"description\":\"verbs is a list of supported kube verbs (this includes get, list, watch, create, update, patch, delete, deletecollection, and proxy)\",\"items\":{\"default\":\"\",\"type\":\"string\"},\"type\":[\"array\",\"null\"],\"nullable\":true},\"version\":{\"description\":\"version is the preferred version of the resource.  Empty implies the version of the containing resource list For subresources, this may have a different value, for example: v1 (while inside a v1beta1 version of the core resource's group)\\\".\",\"type\":\"string\"}},\"required\":[\"name\",\"singularName\",\"namespaced\",\"kind\",\"verbs\"],\"type\":\"object\"},\"io.k8s.apimachinery.pkg.apis.meta.v1.APIResourceList\":{\"description\":\"APIResourceList is a list of APIResource, it is used to expose the name of the resources supported in a specific group and version, and if the resource is namespaced.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"groupVersion\":{\"default\":\"\",\"description\":\"groupVersion is the group and version this APIResourceList is for.\",\"type\":\"string\"},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"resources\":{\"description\":\"resources contains the name of the resources and if they are namespaced.\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.APIResource\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"atomic\",\"nullable\":true}},\"required\":[\"groupVersion\",\"resources\"],\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"\",\"kind\":\"APIResourceList\",\"version\":\"v1\"}]},\"io.k8s.apimachinery.pkg.apis.meta.v1.DeleteOptions\":{\"description\":\"DeleteOptions may be provided when deleting an API object.\",\"properties\":{\"apiVersion\":{\"description\":\"APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources\",\"type\":\"string\"},\"dryRun\":{\"description\":\"When present, indicates that modifications should not be persisted. An invalid or unrecognized dryRun directive will result in an error response and no further processing of the request. Valid values are: - All: all dry run stages will be processed\",\"items\":{\"default\":\"\",\"type\":\"string\"},\"type\":[\"array\",\"null\"],\"x-kubernetes-list-type\":\"atomic\",\"nullable\":true},\"gracePeriodSeconds\":{\"description\":\"The duration in seconds before the object should be deleted. Value must be non-negative integer. The value zero indicates delete immediately. If this value is nil, the default grace period for the specified type will be used. Defaults to a per object value if not specified. zero means delete immediately.\",\"format\":\"int64\",\"type\":\"integer\"},\"ignoreStoreReadErrorWithClusterBreakingPotential\":{\"description\":\"if set to true, it will trigger an unsafe deletion of the resource in case the normal deletion flow fails with a corrupt object error. A resource is considered corrupt if it can not be retrieved from the underlying storage successfully because of a) its data can not be transformed e.g. decryption failure, or b) it fails to decode into an object. NOTE: unsafe deletion ignores finalizer constraints, skips precondition checks, and removes the object from the storage. WARNING: This may potentially break the cluster if the workload associated with the resource being unsafe-deleted relies on normal deletion flow. Use only if you REALLY know what you are doing. The default value is false, and the user must opt in to enable it\",\"type\":\"boolean\"},\"kind\":{\"description\":\"Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds\",\"type\":\"string\"},\"orphanDependents\":{\"description\":\"Deprecated: please use the PropagationPolicy, this field will be deprecated in 1.7. Should the dependent objects be orphaned. If true/false, the \\\"orphan\\\" finalizer will be added to/removed from the object's finalizers list. Either this field or PropagationPolicy may be set, but not both.\",\"type\":\"boolean\"},\"preconditions\":{\"\$ref\":\"https://openapi.invalid/schema/root-3214defad8ecff6cb055.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.Preconditions\"},\"propagationPolicy\":{\"description\":\"Whether and how garbage collection will be performed. Either this field or OrphanDependents may be set, but not both. The default policy is decided by the existing finalizer set in the metadata.finalizers and the resource-specific default policy. Acceptable values are: 'Orphan' - orphan the dependents; 'Background' - allow the garbage collector to delete the dependents in the background; 'Foreground' - a cascading policy that deletes all dependents in the foreground.\",\"type\":\"string\"}},\"type\":\"object\",\"x-kubernetes-group-version-kind\":[{\"group\":\"\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"admission.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"admission.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1beta1\"},{\"group\":\"admissionregistration.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"admissionregistration.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1alpha1\"},{\"group\":\"admissionregistration.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1beta1\"},{\"group\":\"apiextensions.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"apiextensions.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1beta1\"},{\"group\":\"apiregistration.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"apiregistration.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1beta1\"},{\"group\":\"apps\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"apps\",\"kind\":\"DeleteOptions\",\"version\":\"v1beta1\"},{\"group\":\"apps\",\"kind\":\"DeleteOptions\",\"version\":\"v1beta2\"},{\"group\":\"authentication.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"authentication.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1alpha1\"},{\"group\":\"authentication.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1beta1\"},{\"group\":\"authorization.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"authorization.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1beta1\"},{\"group\":\"autoscaling\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"autoscaling\",\"kind\":\"DeleteOptions\",\"version\":\"v2\"},{\"group\":\"autoscaling\",\"kind\":\"DeleteOptions\",\"version\":\"v2beta1\"},{\"group\":\"autoscaling\",\"kind\":\"DeleteOptions\",\"version\":\"v2beta2\"},{\"group\":\"batch\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"batch\",\"kind\":\"DeleteOptions\",\"version\":\"v1beta1\"},{\"group\":\"certificates.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"certificates.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1alpha1\"},{\"group\":\"certificates.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1beta1\"},{\"group\":\"coordination.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"coordination.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1alpha2\"},{\"group\":\"coordination.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1beta1\"},{\"group\":\"discovery.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1\"},{\"group\":\"discovery.k8s.io\",\"kind\":\"DeleteOptions\",\"version\":\"v1beta1\"},{\"group\":\"events.