    nodeallocatableupdateperiodseconds::Union{Absent,Int64,Nothing} = ABSENT
    podinfoonmount::Union{Absent,Bool,Nothing} = ABSENT
    requiresrepublish::Union{Absent,Bool,Nothing} = ABSENT
    selinuxmount::Union{Absent,Bool,Nothing} = ABSENT
    serviceaccounttokeninsecrets::Union{Absent,Bool,Nothing} = ABSENT
    storagecapacity::Union{Absent,Bool,Nothing} = ABSENT
    tokenrequests::Union{Absent,Union{Nothing,Vector{IoK8sApiStorageV1TokenRequest}}} = ABSENT
    volumelifecyclemodes::Union{Absent,Union{Nothing,Vector{String}}} = ABSENT
    additional_properties::Dict{String,Any} = Dict{String,Any}()
end
